	}
	missing := []string{}
	for k, v := range map[string]string{
		"--number": *number, "--date": *date, "--reason": *reason,
	} {
		if strings.TrimSpace(v) == "" {
			missing = append(missing, k)
		}
	}
	if len(missing) > 0 {
		fmt.Fprintln(stderr, "reschedule 缺少必填参数：", strings.Join(missing, "、"))
