177	// TestCertVerdictPositiveNegativeAndBoundary 覆盖正、负测得误差对结论的影响：
178	// 绝对值等于限值（无论正负）显示合格，超过限值明确显示超差；
179	// 超差证书同样录入成功，普通文字与 JSON 结论一致且保留带符号误差。
180	func TestCertVerdictPositiveNegativeAndBoundary(t *testing.T) {
181		dir := chdirTemp(t)
182		path := filepath.Join(dir, "台账.json")
183		registerAllowed(t, path, "M-1", "0.5")
184	
185		now := time.Now()
186		past := func(days int) string { return now.AddDate(0, 0, -days).Format(calibrate.DateLayout) }
187		future := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
188	
189		cases := []struct {
190			number string
191			err    string
192			want   string
193		}{
194			{"C-EQ-POS", "0.5", "合格"},       // 正误差，绝对值恰好等于限值
195			{"C-EQ-NEG", "-0.5", "合格"},      // 负误差，绝对值恰好等于限值
196			{"C-OVER-POS", "0.5001", "超差"},  // 正误差，绝对值超过限值
197			{"C-OVER-NEG", "-0.5001", "超差"}, // 负误差，绝对值超过限值
198		}
199		for i, tc := range cases {
200			args := certFullArgs(path, "M-1", tc.number, past(10+i), future, tc.err)
201			assertCertVerdict(t, args, "M-1", tc.want, tc.err)
202		}
203	
204		// 全部录入成功：历史中四张证书按各自误差带正确结论，符号也原样保留。
205		rv := mustReviewJSON(t, path, "M-1")
206		if len(rv.History) != 4 {
207			t.Fatalf("四张证书都应录入成功，历史有 %d 张", len(rv.History))
208		}
209		want := map[string]struct {
210			pass bool
211			err  float64
212		}{
213			"C-EQ-POS":   {true, 0.5},
214			"C-EQ-NEG":   {true, -0.5},
215			"C-OVER-POS": {false, 0.5001},
216			"C-OVER-NEG": {false, -0.5001},
217		}
218		for _, h := range rv.History {
219			w, ok := want[h.Number]
220			if !ok {
221				t.Fatalf("历史出现意外证书 %s", h.Number)
222			}
223			if h.Pass != w.pass {
224				t.Fatalf("证书 %s 历史结论应为 合格=%v，得到 %v", h.Number, w.pass, h.Pass)
225			}
226			if h.Error != w.err {
227				t.Fatalf("证书 %s 应保留原始带符号误差 %g，得到 %g", h.Number, w.err, h.Error)
228			}
229		}
230	}
