267	// TestCertVerdictFollowsEachInstrumentLimit 同一测得误差放在允许误差不同的
268	// 器具上，结论分别遵从各自限值，不能混用另一件器具的数据。
269	func TestCertVerdictFollowsEachInstrumentLimit(t *testing.T) {
270		dir := chdirTemp(t)
271		path := filepath.Join(dir, "台账.json")
272		registerAllowed(t, path, "M-LOOSE", "1")
273		registerAllowed(t, path, "M-TIGHT", "0.1")
274	
275		now := time.Now()
276		cal := now.AddDate(0, 0, -5).Format(calibrate.DateLayout)
277		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
278	
279		// 同一次校准日、同一个 -0.5 误差：宽松器具合格，严格器具超差。
280		looseArgs := certFullArgs(path, "M-LOOSE", "C-LOOSE", cal, expiry, "-0.5")
281		tightArgs := certFullArgs(path, "M-TIGHT", "C-TIGHT", cal, expiry, "-0.5")
282	
283		looseHuman := runArgs(t, looseArgs...)
284		if looseHuman.code != 0 || !strings.Contains(looseHuman.stdout, "判定：合格") {
285			t.Fatalf("允许误差 1 的器具录入 -0.5 应合格：code=%d %q %s",
286				looseHuman.code, looseHuman.stdout, looseHuman.stderr)
287		}
288		tightHuman := runArgs(t, tightArgs...)
289		if tightHuman.code != 0 || !strings.Contains(tightHuman.stdout, "判定：超差") {
290			t.Fatalf("允许误差 0.1 的器具录入 -0.5 应超差但录入成功：code=%d %q %s",
291				tightHuman.code, tightHuman.stdout, tightHuman.stderr)
292		}
293	
294		// JSON 中证书编号、所属器具、误差都对应本次提交，结论与文字一致。
295		_, looseJSON := runCertJSON(t, looseArgs)
296		_, tightJSON := runCertJSON(t, tightArgs)
297		if looseJSON.Verdict != "合格" || tightJSON.Verdict != "超差" {
298			t.Fatalf("JSON 结论串台：loose=%q tight=%q", looseJSON.Verdict, tightJSON.Verdict)
299		}
300		if looseJSON.Certificate.Number != "C-LOOSE" || looseJSON.Certificate.InstrumentID != "M-LOOSE" ||
301			looseJSON.Certificate.Error != -0.5 {
302			t.Fatalf("宽松器具的 JSON 证书字段不对应本次提交：%+v", looseJSON.Certificate)
303		}
304		if tightJSON.Certificate.Number != "C-TIGHT" || tightJSON.Certificate.InstrumentID != "M-TIGHT" ||
305			tightJSON.Certificate.Error != -0.5 {
306			t.Fatalf("严格器具的 JSON 证书字段不对应本次提交：%+v", tightJSON.Certificate)
307		}
308	
309		// 各器具的最近证书与结论互不混入。
310		looseReview := mustReviewJSON(t, path, "M-LOOSE")
311		tightReview := mustReviewJSON(t, path, "M-TIGHT")
312		if looseReview.Latest == nil || looseReview.Latest.Number != "C-LOOSE" || !looseReview.Latest.Pass {
313			t.Fatalf("宽松器具最近证书应是自身的合格证书：%+v", looseReview.Latest)
314		}
315		if tightReview.Latest == nil || tightReview.Latest.Number != "C-TIGHT" || tightReview.Latest.Pass {
316			t.Fatalf("严格器具最近证书应是自身的超差证书：%+v", tightReview.Latest)
317		}
318	}
