320	// TestCertVerdictIndependentOfInstrumentStatus 证书结论只属于证书本身：
321	// 待校准或停用器具录入合格证书，录入结果仍显示合格；“当前能否使用”另由
322	// 核对按状态判断，不能拿器具的使用判断替换证书结论。
323	func TestCertVerdictIndependentOfInstrumentStatus(t *testing.T) {
324		dir := chdirTemp(t)
325		path := filepath.Join(dir, "台账.json")
326		registerAllowed(t, path, "M-PENDING", "0.5") // 新登记即为待校准
327		registerAllowed(t, path, "M-RETIRED", "0.5")
328		if r := runArgs(t, "status", "-f", path, "--id", "M-RETIRED", "--status", "停用"); r.code != 0 {
329			t.Fatalf("切换停用失败 code=%d stderr=%s", r.code, r.stderr)
330		}
331	
332		now := time.Now()
333		cal := now.AddDate(0, 0, -7).Format(calibrate.DateLayout)
334		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
335	
336		for _, tc := range []struct {
337			id, number, reason string
338		}{
339			{"M-PENDING", "C-PENDING", "待校准"},
340			{"M-RETIRED", "C-RETIRED", "停用"},
341		} {
342			args := certFullArgs(path, tc.id, tc.number, cal, expiry, "-0.2")
343			human := runArgs(t, args...)
344			if human.code != 0 || !strings.Contains(human.stdout, "判定：合格") {
345				t.Fatalf("%s 器具录入合格证书应显示合格：code=%d %q %s",
346					tc.reason, human.code, human.stdout, human.stderr)
347			}
348			_, js := runCertJSON(t, args)
349			if js.Verdict != "合格" || js.Certificate.Number != tc.number ||
350				js.Certificate.InstrumentID != tc.id || js.Certificate.Error != -0.2 {
351				t.Fatalf("%s 器具的证书 JSON 字段不应被使用判断替换：%+v", tc.reason, js)
352			}
353	
354			// 证书本身合格，但器具当前仍不可使用，原因来自状态而非证书超差。
355			rv := mustReviewJSON(t, path, tc.id)
356			if rv.CanUse {
357				t.Fatalf("%s 器具不应因证书合格就能使用", tc.reason)
358			}
359			if !containsStd(rv.Reasons, tc.reason) {
360				t.Fatalf("不可使用的原因应包含%s，得到 %v", tc.reason, rv.Reasons)
361			}
362			if rv.Latest == nil || !rv.Latest.Pass {
363				t.Fatalf("%s 器具的最近证书自身结论仍应是合格：%+v", tc.reason, rv.Latest)
364			}
365		}
366	}
