368	// TestBackfillOlderPassingCertKeepsNewerFailingLatest 守住补录主场景：
369	// 器具在用、已有一张校准日期较新的超差证书，再补录一张校准日期较早、合格且
370	// 未到期的证书——补录结果必须显示旧证书合格并进入历史，但最近证书仍是较新
371	// 的超差证书，申请使用仍因最近证书超差被拒绝。先后依据校准日期，而不是证书
372	// 编号或录入顺序（这里较新证书编号 C-1 更小、录入更早）。
373	func TestBackfillOlderPassingCertKeepsNewerFailingLatest(t *testing.T) {
374		dir := chdirTemp(t)
375		path := filepath.Join(dir, "台账.json")
376		registerAllowed(t, path, "M-1", "0.5")
377		if r := runArgs(t, "status", "-f", path, "--id", "M-1", "--status", "在用"); r.code != 0 {
378			t.Fatalf("切换在用失败 code=%d stderr=%s", r.code, r.stderr)
379		}
380	
381		now := time.Now()
382		newerCal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
383		olderCal := now.AddDate(0, 0, -200).Format(calibrate.DateLayout)
384		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
385	
386		// 先录入校准日期较新的超差证书（编号 C-1，按编号反而更小）。
387		newer := certFullArgs(path, "M-1", "C-1", newerCal, expiry, "0.8")
388		r := runArgs(t, newer...)
389		if r.code != 0 || !strings.Contains(r.stdout, "已录入新证书") ||
390			!strings.Contains(r.stdout, "判定：超差") {
391			t.Fatalf("较新超差证书应录入成功并显示超差：code=%d %q %s", r.code, r.stdout, r.stderr)
392		}
393	
394		// 补录前：历史 1 张、最近证书超差、使用被拒绝并留痕。
395		before := mustReviewJSON(t, path, "M-1")
396		if len(before.History) != 1 || before.Latest == nil || before.Latest.Number != "C-1" || before.Latest.Pass {
397			t.Fatalf("补录前最近证书应是超差的 C-1：%+v", before)
398		}
399		use1 := runArgs(t, "use", "--id", "M-1", "-f", path)
400		if use1.code != 1 || !strings.Contains(use1.stderr, "超差") {
401			t.Fatalf("最近证书超差应拒绝使用，code=%d stderr=%q", use1.code, use1.stderr)
402		}
403	
404		// 补录校准日期较早、合格、未到期的旧证书（编号 C-9 更大、录入更晚）。
405		older := certFullArgs(path, "M-1", "C-9", olderCal, expiry, "-0.1")
406		jr, js := runCertJSON(t, older)
407		if jr.code != 0 || !js.Accepted || js.Duplicate {
408			t.Fatalf("旧合格证书应作为新证书录入成功：code=%d stdout=%q stderr=%s",
409				jr.code, jr.stdout, jr.stderr)
410		}
411		if js.Verdict != "合格" {
412			t.Fatalf("补录结果必须显示旧证书自身合格，不能被最近证书的超差覆盖，得到 %q", js.Verdict)
413		}
414		if js.Certificate.Number != "C-9" || js.Certificate.InstrumentID != "M-1" ||
415			js.Certificate.Error != -0.1 || js.Certificate.CalDate != olderCal {
416			t.Fatalf("JSON 证书字段应对应本次补录：%+v", js.Certificate)
417		}
418		// 同内容普通文字重提：结论仍为合格，并标明返回原证书。
419		human2 := runArgs(t, older...)
420		if human2.code != 0 || !strings.Contains(human2.stdout, "判定：合格") ||
421			!strings.Contains(human2.stdout, "未增加历史") {
422			t.Fatalf("普通文字下补录证书也应显示合格：code=%d %q", human2.code, human2.stdout)
423		}
424	
425		// 补录后：历史增加这张证书；最近证书仍是校准日期较新的超差 C-1，
426		// 不能因为补录证书合格就解除使用限制；器具状态保持在用。
427		after := mustReviewJSON(t, path, "M-1")
428		if len(after.History) != len(before.History)+1 {
429			t.Fatalf("补录应只增加一张历史证书：%d -> %d",
430				len(before.History), len(after.History))
431		}
432		if after.Instrument.Status != "在用" {
433			t.Fatalf("补录证书不应改写器具状态，得到 %s", after.Instrument.Status)
434		}
435		if after.Latest == nil || after.Latest.Number != "C-1" ||
436			after.Latest.CalDate != newerCal || after.Latest.Error != 0.8 || after.Latest.Pass {
437			t.Fatalf("最近证书必须仍是较新的超差 C-1（按校准日期而非编号/录入顺序）：%+v", after.Latest)
438		}
439		found := false
440		for i := range after.History {
441			h := after.History[i]
442			if h.Number == "C-9" {
443				found = true
444				if !h.Pass {
445					t.Fatal("历史中的旧证书应显示合格")
446				}
447				if h.Expired {
448					t.Fatal("补录的旧证书应未到期")
449				}
450				if h.Error != -0.1 {
451					t.Fatalf("旧证书应保留原始带符号误差 -0.1，得到 %g", h.Error)
452				}
453			}
454			if h.Number == "C-1" && !h.Pass {
455				// 较新证书结论同样保持超差。
456			}
457		}
458		if !found {
459			t.Fatalf("历史中应增加补录的 C-9：%+v", after.History)
460		}
461		if after.CanUse || !containsStd(after.Reasons, "超差") {
462			t.Fatalf("补录合格旧证书不应解除使用限制：canUse=%v reasons=%v",
463				after.CanUse, after.Reasons)
464		}
465	
466		// 再次申请使用：仍因最近证书 C-1 超差被拒绝，并新增一条拒绝留痕。
467		use2 := runArgs(t, "use", "--id", "M-1", "-f", path, "--json")
468		if use2.code != 1 || !strings.Contains(use2.stdout, `"allowed": false`) ||
469			!strings.Contains(use2.stdout, "超差") {
470			t.Fatalf("补录后申请使用仍应因最近证书超差被拒绝：code=%d stdout=%q",
471				use2.code, use2.stdout)
472		}
473		final := mustReviewJSON(t, path, "M-1")
474		if len(final.Rejections) != 2 {
475			t.Fatalf("两次拒绝都应留痕且补录不改写历史，得到 %d 条", len(final.Rejections))
476		}
477		for i, rej := range final.Rejections {
478			if rej.Allowed || !containsStd(rej.Reasons, "超差") {
479				t.Fatalf("第 %d 条拒绝记录应保留申请当时的超差原因：%+v", i+1, rej)
480			}
481		}
482	}
