484	// TestBackfillOlderFailingCertKeepsInstrumentUsable 反方向守住同一条边界：
485	// 器具在用、最近证书合格时补录一张更早的超差证书，补录结果必须如实显示超差，
486	// 但最近证书与当前能否使用都不被这张旧证书改变。
487	func TestBackfillOlderFailingCertKeepsInstrumentUsable(t *testing.T) {
488		dir := chdirTemp(t)
489		path := filepath.Join(dir, "台账.json")
490		registerAllowed(t, path, "M-2", "0.5")
491		if r := runArgs(t, "status", "-f", path, "--id", "M-2", "--status", "在用"); r.code != 0 {
492			t.Fatalf("切换在用失败 code=%d stderr=%s", r.code, r.stderr)
493		}
494	
495		now := time.Now()
496		newerCal := now.AddDate(0, 0, -30).Format(calibrate.DateLayout)
497		olderCal := now.AddDate(0, 0, -200).Format(calibrate.DateLayout)
498		expiry := now.AddDate(10, 0, 0).Format(calibrate.DateLayout)
499	
500		// 较新的合格证书：器具当前可使用。
501		newer := certFullArgs(path, "M-2", "C-2", newerCal, expiry, "0.1")
502		if r := runArgs(t, newer...); r.code != 0 ||
503			!strings.Contains(r.stdout, "判定：合格") {
504			t.Fatalf("较新合格证书录入异常：code=%d %q %s", r.code, r.stdout, r.stderr)
505		}
506		if u := runArgs(t, "use", "--id", "M-2", "-f", path); u.code != 0 {
507			t.Fatalf("最近证书合格未到期时应允许使用，code=%d stderr=%s", u.code, u.stderr)
508		}
509	
510		// 补录更早的超差证书：本次录入结果必须明确显示超差。
511		older := certFullArgs(path, "M-2", "C-1", olderCal, expiry, "-5")
512		jr, js := runCertJSON(t, older)
513		if jr.code != 0 || !js.Accepted || js.Duplicate {
514			t.Fatalf("旧超差证书也应作为新证书录入成功：code=%d stdout=%q stderr=%s",
515				jr.code, jr.stdout, jr.stderr)
516		}
517		if js.Verdict != "超差" || js.Certificate.Number != "C-1" ||
518			js.Certificate.InstrumentID != "M-2" || js.Certificate.Error != -5 {
519			t.Fatalf("补录结果应如实显示本次证书超差且字段对应提交：%+v", js)
520		}
521	
522		// 最近证书仍是较新的合格 C-2，器具当前可以使用，使用申请不因旧超差证书被拒。
523		rv := mustReviewJSON(t, path, "M-2")
524		if len(rv.History) != 2 {
525			t.Fatalf("补录应使历史变为 2 张，得到 %d", len(rv.History))
526		}
527		if rv.Latest == nil || rv.Latest.Number != "C-2" || !rv.Latest.Pass {
528			t.Fatalf("最近证书应仍是较新的合格 C-2：%+v", rv.Latest)
529		}
530		if !rv.CanUse || len(rv.Reasons) != 0 {
531			t.Fatalf("最近证书合格时旧超差证书不应限制使用：canUse=%v reasons=%v",
532				rv.CanUse, rv.Reasons)
533		}
534		for _, h := range rv.History {
535			switch h.Number {
536			case "C-1":
537				if h.Pass || h.Error != -5 {
538					t.Fatalf("旧超差证书应保留超差结论与带符号误差：%+v", h)
539				}
540			case "C-2":
541				if !h.Pass {
542					t.Fatalf("较新合格证书不应被旧证书改写结论：%+v", h)
543				}
544			}
545		}
546		if u := runArgs(t, "use", "--id", "M-2", "-f", path, "--json"); u.code != 0 ||
547			!strings.Contains(u.stdout, `"allowed": true`) {
548			t.Fatalf("补录旧超差证书后仍应允许使用：code=%d stdout=%q stderr=%s",
549				u.code, u.stdout, u.stderr)
550		}
551	}
552	
553	func containsStd(haystack []string, needle string) bool {
554		for _, s := range haystack {
555			if strings.Contains(s, needle) {
556				return true
557			}
558		}
559		return false
560	}
561

