1	package calibrate
2	
3	import (
4		"errors"
5		"math"
6		"path/filepath"
7		"strings"
8		"testing"
9		"time"
10	)
11	
12	// fakeClock 是可手动拨动的本机时钟。
13	type fakeClock struct{ t time.Time }
14	
15	func (c *fakeClock) now() time.Time { return c.t }
16	
17	func newTestLedger(t *testing.T, clock *fakeClock) *Ledger {
18		t.Helper()
19		path := filepath.Join(t.TempDir(), "ledger.json")
20		l, err := openAt(path, clock.now)
21		if err != nil {
22			t.Fatalf("open ledger: %v", err)
23		}
24		return l
25	}
26	
27	func mustDate(t *testing.T, s string) time.Time {
28		t.Helper()
29		d, err := time.Parse(DateLayout, s)
30		if err != nil {
31			t.Fatalf("bad test date %s: %v", s, err)
32		}
33		return d
34	}
35	
36	func TestRegisterValidation(t *testing.T) {
37		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
38		l := newTestLedger(t, clock)
39	
40		cases := []struct {
41			name string
42			in   RegisterInput
43		}{
44			{"空白编号", RegisterInput{ID: "   ", Name: "万用表", AllowedError: 0.1}},
45			{"空白名称", RegisterInput{ID: "M-1", Name: "\t", AllowedError: 0.1}},
46			{"负误差", RegisterInput{ID: "M-1", Name: "万用表", AllowedError: -0.01}},
47			{"NaN误差", RegisterInput{ID: "M-1", Name: "万用表", AllowedError: math.NaN()}},
48			{"正无穷误差", RegisterInput{ID: "M-1", Name: "万用表", AllowedError: math.Inf(1)}},
49			{"负零可以", RegisterInput{ID: "M-ok", Name: "零限", AllowedError: 0}},
50		}
51		for _, tc := range cases {
52			t.Run(tc.name, func(t *testing.T) {
53				if strings.Contains(tc.name, "可以") {
54					if _, err := l.Register(tc.in); err != nil {
55						t.Fatalf("零误差应被接受: %v", err)
56					}
57					return
58				}
59				if _, err := l.Register(tc.in); !IsValidation(err) {
60					t.Fatalf("应返回校验错误，得到 %v", err)
61				}
62			})
63		}
64	
65		// 新器具处于待校准状态。
66		inst, err := l.Register(RegisterInput{ID: "M-1", Name: "万用表", AllowedError: 0.5})
67		if err != nil {
68			t.Fatalf("register: %v", err)
69		}
70		if inst.Status != StatusPending {
71			t.Fatalf("新器具状态应为待校准，得到 %s", inst.Status)
72		}
73	
74		// 编号重复明确拒绝，原记录不变；名称两侧空白被裁剪。
75		before := len(l.Instruments())
76		_, err = l.Register(RegisterInput{ID: "  M-1  ", Name: "另一个", AllowedError: 1})
77		if !IsValidation(err) || !strings.Contains(err.Error(), "已存在") {
78			t.Fatalf("重复编号应报校验错误，得到 %v", err)
79		}
80		if len(l.Instruments()) != before {
81			t.Fatal("拒绝重复编号后器具数量变化")
82		}
83		if got := l.findInstrument("M-1"); got.Name != "万用表" {
84			t.Fatalf("原记录被改动：名称=%s", got.Name)
85		}
86	
87		// 无效登记不留记录：前面 4 个失败用例 + 成功 2 件。
88		if len(l.Instruments()) != 2 {
89			t.Fatalf("无效录入留下了记录，共 %d 件", len(l.Instruments()))
90		}
91	}
92	
93	func TestStatusTransitions(t *testing.T) {
94		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
95		l := newTestLedger(t, clock)
96		mustRegister(t, l, "M-1", "万用表", 0.5)
97	
98		if err := l.SetStatus("M-1", StatusInUse); err != nil {
99			t.Fatalf("set in-use: %v", err)
100		}
101		if l.findInstrument("M-1").Status != StatusInUse {
102			t.Fatal("未切换为在用")
103		}
104		// 切换为在用本身不代表已经校准：没有证书时使用仍被拒绝。
105		d, err := l.RequestUse("M-1")
106		if err != nil {
107			t.Fatalf("request use: %v", err)
108		}
109		if d.Allowed || !containsReason(d.Reasons, "没有校准证书") {
110			t.Fatalf("在用但无证书应拒绝，得到 allowed=%v reasons=%v", d.Allowed, d.Reasons)
111		}
112		// 停用不删除证书和使用记录：先补证书，再停用，再核对历史仍在。
113		mustAddCert(t, l, CertificateInput{
114			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
115			Expiry: "2027-09-01", Method: "规范A", Error: 0.1, Summary: "合格批次",
116		})
117		if err := l.SetStatus("M-1", StatusRetired); err != nil {
118			t.Fatalf("retire: %v", err)
119		}
120		r, err := l.Review("M-1")
121		if err != nil {
122			t.Fatalf("review: %v", err)
123		}
124		if len(r.History) != 1 || len(r.Rejections) != 1 {
125			t.Fatalf("停用后证书或使用记录被删除：历史=%d 拒绝=%d", len(r.History), len(r.Rejections))
126		}
127		if err := l.SetStatus("missing", StatusInUse); !errors.Is(err, ErrNotFound) {
128			t.Fatalf("未知器具应报 ErrNotFound，得到 %v", err)
129		}
130	}
131	
132	func TestCertificateValidation(t *testing.T) {
133		clock := &fakeClock{t: mustDate(t, "2026-10-02")}
134		l := newTestLedger(t, clock)
135		mustRegister(t, l, "M-1", "万用表", 0.5)
136	
137		base := CertificateInput{
138			InstrumentID: "M-1", Number: "C-1", CalDate: "2026-09-01",
139			Expiry: "2027-09-01", Method: "规范A", Error: 0.1, Summary: "摘要",
140		}
141		valid := func(mut func(*CertificateInput)) CertificateInput {
142			c := base
143			mut(&c)
144			return c
145		}
146	
147		bad := []struct {
148			name string
149			in   CertificateInput
150		}{
151			{"未知器具", valid(func(c *CertificateInput) { c.InstrumentID = "X-9" })},
152			{"空白证书编号", valid(func(c *CertificateInput) { c.Number = "  " })},
153			{"空白方法", valid(func(c *CertificateInput) { c.Method = "\t" })},
154			{"空白摘要", valid(func(c *CertificateInput) { c.Summary = "" })},
